#!/bin/bash
# Generated by akmesh ({created}) for {name}
{sbatch_lines}
#SBATCH --job-name=akmesh_{name}
#SBATCH --output={out_dir}/{log}_%j.out
#SBATCH --error={out_dir}/{log}_%j.err

set -euo pipefail

{setup}

export PYTHONPATH="{pythonpath}${{PYTHONPATH:+:$PYTHONPATH}}"
export OMP_NUM_THREADS=1 MKL_NUM_THREADS=1 OPENBLAS_NUM_THREADS=1
# temporary files on the parallel file system (node-local /tmp is too small)
mkdir -p "{out_dir}/tmp"
export TMPDIR="{out_dir}/tmp" OCSMESH_SHARED_TMPDIR="{out_dir}/tmp"

cd "{out_dir}"
echo "akmesh {name}  job ${{SLURM_JOB_ID:-n/a}}  node ${{SLURM_NODELIST:-n/a}}  $(date)"
{launcher} python -m stofs3dak_mesh.cli {command}
rm -rf "{out_dir}/tmp"
echo "=== DONE $(date) ==="
